pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value, bytes memory _data) public {
        address deployer = address(this);
        vm.assume(_target != address(0) || _value <= address(c).balance);
        c.sendMoney(_target, _value, _data);
        assertTrue(c.owner() == deployer);
    }
}

